document.addEventListener('DOMContentLoaded',()=>{const root=document.querySelector('[data-chunk-upload]');if(!root)return;const el=n=>root.querySelector('[data-up-'+n+']'),county=el('county'),type=el('owner-type'),owner=el('owner-id'),sector=el('sector'),slot=el('slot'),file=el('file'),status=el('status'),start=el('start');const entities=JSON.parse(el('entities').textContent);let busy=false,control={};const choices=(s,rows,label)=>s.replaceChildren(new Option(label,''),...rows.map(x=>new Option(x.name,String(x.id))));
const refresh=()=>{sector.disabled=true;choices(sector,[],'Choose institution first');const kind=type.value.split('\\').pop();choices(owner,kind==='County'?entities.counties.filter(x=>String(x.id)===county.value):kind==='CountyInstitution'?entities.institutions.filter(x=>String(x.county_id)===county.value):entities.venues,'Choose owner');};county.onchange=refresh;type.onchange=refresh;
owner.onchange=async()=>{sector.disabled=true;if(type.value!=='App\\Models\\CountyInstitution')return;try{const inst=entities.institutions.find(x=>String(x.id)===owner.value);const r=await fetch('/admin/media-flow/'+encodeURIComponent(inst.slug)+'/sectors',{headers:{Accept:'application/json'},credentials:'same-origin'}),d=await r.json();if(!r.ok)throw Error(d.message);choices(sector,d.sectors,'Choose linked sector');sector.disabled=false;}catch(e){status.textContent=e.message}};
start.onclick=async()=>{if(busy)return;const f=file.files[0];if(!f||!owner.value||!el('title').value.trim())return status.textContent='Select a file, owner and title.';if(type.value==='App\\Models\\CountyInstitution'&&!sector.value)return status.textContent='Choose linked sector.';busy=true;start.disabled=true;control={controller:new AbortController()};control.signal=control.controller.signal;el('pause').hidden=false;el('cancel').hidden=false;try{const result=await KiccEntityUploader.upload(f,{owner_type:type.value,owner_id:owner.value,sector_id:sector.value||null,slot:slot.value,title:el('title').value},(n,t)=>{el('progress').value=n;status.textContent=t;},control);el('log').hidden=false;el('log').textContent=JSON.stringify(result,null,2);const link=el('preview');link.href=result.owner_url;link.hidden=false;link.textContent='Open public owner page ↗';start.textContent='Upload another video';}catch(e){status.textContent=e.name==='AbortError'?'Paused. Reselect the same file and Resume upload.':e.message;start.textContent='Resume upload';}finally{busy=false;start.disabled=false;el('pause').hidden=true;}};
el('pause').onclick=()=>{control.paused=true;control.controller?.abort();};el('cancel').onclick=async()=>{control.paused=true;control.controller?.abort();try{await KiccEntityUploader.cancel(control);status.textContent='Pending upload cancelled. Published videos are unchanged.';el('cancel').hidden=true;start.textContent='Upload & publish';}catch(e){status.textContent=e.message;}};
const q=new URLSearchParams(location.search);if(q.has('county'))county.value=q.get('county');refresh();if(q.get('institution')){type.value='App\\Models\\CountyInstitution';refresh();const i=entities.institutions.find(i=>i.slug===q.get('institution'));if(i){county.value=String(i.county_id);refresh();owner.value=String(i.id);owner.dispatchEvent(new Event('change'));}}});
